H.background();
const w = H.W, h = H.H;
const Th = Math.max(10, P.Th), Tc = H.clamp(P.Tc, 1, Th - 1);  // reservoir temps (K)
const Qh = Math.max(1, P.Qh);            // heat drawn from hot reservoir (J)
const eff = 1 - Tc / Th;                 // Carnot (max) efficiency
const Wout = eff * Qh;                   // work output
const Qc = Qh - Wout;                    // heat dumped to cold reservoir
const cx = w * 0.40;
const hotY = 90, coldY = h - 90, engY = h * 0.5;
H.rect(cx - 130, hotY - 34, 260, 56, { fill: "#3a1c2a", stroke: H.colors.warn, width: 2, radius: 8 });
H.text("HOT  Th = " + Th.toFixed(0) + " K", cx - 70, hotY, { color: H.colors.warn, size: 14, weight: 700 });
H.rect(cx - 130, coldY - 22, 260, 56, { fill: "#16263f", stroke: H.colors.accent, width: 2, radius: 8 });
H.text("COLD  Tc = " + Tc.toFixed(0) + " K", cx - 78, coldY + 12, { color: H.colors.accent, size: 14, weight: 700 });
// engine wheel that spins with t
const rEng = 46;
H.circle(cx, engY, rEng, { fill: H.colors.panel, stroke: H.colors.violet, width: 3 });
for (let i = 0; i < 8; i++) {
  const a = t * 2 + i * H.TAU / 8;
  H.line(cx, engY, cx + Math.cos(a) * rEng, engY + Math.sin(a) * rEng, { color: H.colors.violet, width: 1.5 });
}
H.text("engine", cx - 22, engY + 4, { color: H.colors.sub, size: 12 });
H.arrow(cx, hotY + 24, cx, engY - rEng - 4, { color: H.colors.warn, width: 4 });
H.text("Qh = " + Qh.toFixed(0) + " J", cx + 14, (hotY + engY) / 2, { color: H.colors.warn, size: 13 });
H.arrow(cx, engY + rEng + 4, cx, coldY - 24, { color: H.colors.accent, width: 4 });
H.text("Qc = " + Qc.toFixed(0) + " J", cx + 14, (engY + coldY) / 2, { color: H.colors.accent, size: 13 });
const wob = 6 * Math.sin(t * 3);
H.arrow(cx + rEng + 4, engY, cx + rEng + 90 + wob, engY, { color: H.colors.good, width: 4 });
H.text("W = " + Wout.toFixed(0) + " J", cx + rEng + 24, engY - 12, { color: H.colors.good, size: 13 });
// efficiency bar
const bx = w - 70, byTop = 110, bh = h - 220;
H.rect(bx, byTop, 24, bh, { stroke: H.colors.axis, width: 1.5 });
H.rect(bx, byTop + bh * (1 - eff), 24, bh * eff, { fill: H.colors.good });
H.text((eff * 100).toFixed(0) + "%", bx - 6, byTop - 10, { color: H.colors.good, size: 13, weight: 700 });
H.text("η", bx + 6, byTop + bh + 18, { color: H.colors.sub, size: 14 });
H.text("Heat engine: η = W/Qh = 1 − Tc/Th", 24, 30, { color: H.colors.ink, size: 17, weight: 700 });
H.text("Qh = " + Qh.toFixed(0) + " J → W = " + Wout.toFixed(0) + " J + Qc = " + Qc.toFixed(0) + " J    η = " + (eff * 100).toFixed(1) + "%", 24, 54, { color: H.colors.sub, size: 13 });
